add_filter( 'woocommerce_login_redirect', 'perfectpixel_login_redirect_by_role', 30, 2 );

function perfectpixel_login_redirect_by_role( $redirect, $user ) {
	if ( ! $user instanceof WP_User || ! empty( $_POST['redirect'] ) ) {
		return $redirect;
	}
	foreach ( explode( '|', '{{login_redirect_roles}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && in_array( $parts[0], (array) $user->roles, true ) && '' !== $parts[1] ) {
			return wp_validate_redirect( 0 === strpos( $parts[1], '/' ) ? home_url( $parts[1] ) : $parts[1], $redirect );
		}
	}
	return $redirect;
}
